                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-24' and business_date <= date '2025-06-24' and weight_ndo>0 and id_cppib_index = 'SP500_20_GR_USD_0_0' and security_id is not null

/* cppi::cf4a3b41865ab533d9b16b4b0a6363979b9b9f5ef7a4104f8c77d2a8b97dd494 */
SELECT * FROM ci_etl_db_dev.ci_capital_pipeline_sentry_unsettled_transactions_transformed
                WHERE CAST(extract_timestamp AS TIMESTAMP) = TIMESTAMP '2025-06-25 13:09:42'

/* cppi::c4e654b0e6b86204f68de00132d8e2f963886b951c8b1a430c020a5902bbe11a */
select * from trades_deals.scd_transactions_entity 
limit 1

/* cppi::3fe304894eb8c4b9728046c317e47a01c68a485ccbf460e89daf8adfaa689ebe */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-02' and end_date = '2025-04-02')
and start_date = '2025-04-02' and end_date = '2025-04-02'

